#include <os/fs.h>
#include <os/disk.h>
#include <os/file.h>
#include <os/mm.h>
#include <os/sched.h>
#include <os/irq.h>
#include <os/string.h>
#include <assert.h>

#define FS_PATH_MAX 256
#define FS_NAME_MAX 28

fd_t fd_list[10];

static int copy_user_string(char *dst, const char *src, int max_len)
{
    int i = 0;

    if (src == NULL || max_len <= 0) {
        return 0;
    }

    while (i < max_len - 1) {
        dst[i] = src[i];
        if (dst[i] == '\0') {
            return 1;
        }
        i++;
    }

    dst[max_len - 1] = '\0';
    return 0;
}

static int valid_leaf_name(const char *name)
{
    return name != NULL && name[0] != '\0' &&
           strlen(name) < (int)sizeof(((dir_entry_t *)0)->name) &&
           strcmp(name, ".") && strcmp(name, "..");
}

static int create_file_kernel(const char *path)
{
    uint16_t parent_inode_id;
    uint8_t parent_type;
    char leaf_name[FS_NAME_MAX + 1];

    if (!fs_resolve_path(path, 1, &parent_inode_id, &parent_type, NULL,
                         leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name) ||
        fs_lookup_entry(parent_inode_id, leaf_name, NULL, NULL, NULL)) {
        return 0;
    }

    uint16_t inode_id = alloc_inode();
    if (inode_id == 0xffff) {
        return 0;
    }

    inode_t inode;
    memset(&inode, 0, sizeof(inode));
    inode.mode = FILE;
    inode.owner = current_running[cpu_id]->pid;
    inode.link = 1;
    fs_write_inode_copy(inode_id, &inode);

    if (!fs_add_entry(parent_inode_id, leaf_name, FILE, inode_id)) {
        free_inode(inode_id);
        return 0;
    }

    return 1;
}

int do_touch(char* filename)
{
    char path[FS_PATH_MAX];

    enable_sum();
    int copied = copy_user_string(path, filename, sizeof(path));
    disable_sum();
    if (!copied) {
        return 0;
    }

    return create_file_kernel(path);
}

int do_cat(char* filename, char* buffer)
{
    char path[FS_PATH_MAX];
    uint16_t inode_id;
    uint8_t type;
    inode_t inode;
    int copied_bytes = 0;

    enable_sum();
    if (!copy_user_string(path, filename, sizeof(path)) ||
        !fs_resolve_path(path, 0, &inode_id, &type, NULL, NULL) ||
        type != FILE) {
        if (buffer != NULL) {
            buffer[0] = '\0';
        }
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(inode_id, &inode);
    int remaining = inode.size < PAGE_SIZE - 1 ? inode.size : PAGE_SIZE - 1;
    while (remaining > 0) {
        uint32_t block_id = fs_get_data_block(inode_id, copied_bytes / PAGE_SIZE, 0);
        int chunk = remaining > PAGE_SIZE ? PAGE_SIZE : remaining;
        if (block_id == 0xffffffff) {
            disable_sum();
            return 0;
        }

        if (block_id == 0) {
            memset(buffer + copied_bytes, 0, chunk);
        } else {
            read_block(block_id);
            memcpy((uint8_t *)(buffer + copied_bytes),
                   (const uint8_t *)BLOCK_CACHE, chunk);
        }
        copied_bytes += chunk;
        remaining -= chunk;
    }

    buffer[copied_bytes] = '\0';
    disable_sum();
    return 1;
}

int do_fopen(char* filename, int access)
{
    char path[FS_PATH_MAX];
    uint16_t inode_id;
    uint8_t type;

    if (access != O_RDONLY && access != O_WRONLY && access != O_RDWR) {
        return -1;
    }

    enable_sum();
    int copied = copy_user_string(path, filename, sizeof(path));
    disable_sum();
    if (!copied) {
        return -1;
    }

    if (!fs_resolve_path(path, 0, &inode_id, &type, NULL, NULL)) {
        if (access == O_RDONLY || !create_file_kernel(path) ||
            !fs_resolve_path(path, 0, &inode_id, &type, NULL, NULL)) {
            return -1;
        }
    }
    if (type != FILE) {
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        if (fd_list[i].access == O_EMPTY) {
            fd_list[i].inode = inode_id;
            fd_list[i].access = access;
            fd_list[i].rd_pos = 0;
            fd_list[i].wr_pos = 0;
            return i;
        }
    }

    return -1;
}

int do_fread(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= 10 || fd_list[fd].access == O_EMPTY || size <= 0 ||
        (fd_list[fd].access != O_RDONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    inode_t inode;
    fs_read_inode_copy(fd_list[fd].inode, &inode);
    if (fd_list[fd].rd_pos >= inode.size) {
        return 0;
    }

    uint64_t remaining = inode.size - fd_list[fd].rd_pos;
    if ((uint64_t)size < remaining) {
        remaining = size;
    }

    enable_sum();
    int copied = 0;
    while (remaining > 0) {
        uint32_t block_idx = fd_list[fd].rd_pos / PAGE_SIZE;
        uint32_t block_offset = fd_list[fd].rd_pos % PAGE_SIZE;
        uint32_t block_id = fs_get_data_block(fd_list[fd].inode, block_idx, 0);
        int chunk = PAGE_SIZE - block_offset;
        if ((uint64_t)chunk > remaining) {
            chunk = remaining;
        }
        if (block_id == 0xffffffff) {
            disable_sum();
            return copied;
        }

        if (block_id == 0) {
            memset(buffer + copied, 0, chunk);
        } else {
            read_block(block_id);
            memcpy((uint8_t *)(buffer + copied),
                   (const uint8_t *)(BLOCK_CACHE + block_offset), chunk);
        }

        fd_list[fd].rd_pos += chunk;
        copied += chunk;
        remaining -= chunk;
    }
    disable_sum();

    return copied;
}

int do_fwrite(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= 10 || fd_list[fd].access == O_EMPTY || size <= 0 ||
        (fd_list[fd].access != O_WRONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    inode_t inode;
    fs_read_inode_copy(fd_list[fd].inode, &inode);

    enable_sum();
    int written = 0;
    while (written < size) {
        uint32_t block_idx = fd_list[fd].wr_pos / PAGE_SIZE;
        uint32_t block_offset = fd_list[fd].wr_pos % PAGE_SIZE;
        uint32_t block_id = fs_get_data_block(fd_list[fd].inode, block_idx, 1);
        int chunk = PAGE_SIZE - block_offset;
        if (chunk > size - written) {
            chunk = size - written;
        }
        if (block_id == 0xffffffff) {
            break;
        }

        read_block(block_id);
        memcpy((uint8_t *)(BLOCK_CACHE + block_offset),
               (const uint8_t *)(buffer + written), chunk);
        write_block(block_id);

        fd_list[fd].wr_pos += chunk;
        written += chunk;
    }
    disable_sum();

    if (inode.size < fd_list[fd].wr_pos) {
        inode.size = fd_list[fd].wr_pos;
        fs_write_inode_copy(fd_list[fd].inode, &inode);
    }

    return written;
}

void do_fclose(int fd)
{
    fd_list[fd].access = O_EMPTY;
}

