    fs_write_inode_copy(new_inode_id, &new_inode);

    read_block(new_block_id);
    memset((void *)cached_block_base, 0, PAGE_SIZE);
    dir_t *new_dir = (dir_t *)cached_block_base;
    init_entry(&new_dir->entry[0], DIR, ".", new_inode_id);
    init_entry(&new_dir->entry[1], DIR, "..", parent_inode_id);
    write_block(new_block_id);

    int ret = fs_add_entry(parent_inode_id, leaf_name, DIR, new_inode_id);
    if (!ret) {
        free_block(new_block_id);
        free_inode(new_inode_id);
    }
    disable_sum();
    return ret;
}

int do_rmdir(char* dirname)
{
    char leaf_name[29];
    uint16_t parent_inode_id;
    uint8_t parent_type;

    enable_sum();
    if (!fs_resolve_path(dirname, 1, &parent_inode_id, &parent_type, NULL, leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name)) {
        disable_sum();
        return 0;
    }

    dir_entry_t target_entry;
    uint32_t entry_block;
    uint32_t entry_slot;
    if (!fs_lookup_entry(parent_inode_id, leaf_name, &target_entry,
                         &entry_block, &entry_slot) ||
        target_entry.type != DIR) {
        disable_sum();
        return 0;
    }

    if (target_entry.inode == superblock->root_inode_id) {
        disable_sum();
        return 0;
    }

    inode_t dir_inode;
    fs_read_inode_copy(target_entry.inode, &dir_inode);
    uint32_t block_count = inode_block_count(target_entry.inode, &dir_inode);
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t dir_block = fs_get_data_block(target_entry.inode, logical_idx, 0);
        if (dir_block == 0xffffffff ||
            (dir_block == 0 &&
             !is_root_block_ref(target_entry.inode, &dir_inode, logical_idx, dir_block))) {
            continue;
        }

        read_block(dir_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            if (dir->entry[i].type != EMPTY &&
                strcmp((char *)dir->entry[i].name, ".") &&
                strcmp((char *)dir->entry[i].name, "..")) {
                disable_sum();
                return 0;
            }
        }
    }

    read_block(entry_block);
    dir_t *parent_dir = (dir_t *)cached_block_base;
    memset(&parent_dir->entry[entry_slot], 0, sizeof(parent_dir->entry[entry_slot]));
    write_block(entry_block);

    inode_t parent_inode;
    fs_read_inode_copy(parent_inode_id, &parent_inode);
    if (parent_inode.size >= sizeof(dir_entry_t)) {
        parent_inode.size -= sizeof(dir_entry_t);
    }
    fs_write_inode_copy(parent_inode_id, &parent_inode);

    free_inode_data_blocks(target_entry.inode, &dir_inode);
    free_inode(target_entry.inode);
    if (current_dir_inode == target_entry.inode) {
        current_dir_inode = parent_inode_id;
        current_dir_block = parent_inode.direct_blocks[0];
    }
    disable_sum();
    return 1;
}

int do_ls(char* dirname, int mode, int* print_location_y)
{
    uint16_t dir_inode_id;
    uint8_t dir_type;
    inode_t dir_inode;

    enable_sum();
    if ((dirname[0] == '\0' &&
         !fs_resolve_path("", 0, &dir_inode_id, &dir_type, NULL, NULL)) ||
        (dirname[0] != '\0' &&
         !fs_resolve_path(dirname, 0, &dir_inode_id, &dir_type, NULL, NULL)) ||
        dir_type != DIR) {
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(dir_inode_id, &dir_inode);
    uint32_t block_count = inode_block_count(dir_inode_id, &dir_inode);
    int printed_lines = 0;
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t dir_block = fs_get_data_block(dir_inode_id, logical_idx, 0);
        if (dir_block == 0xffffffff ||
            (dir_block == 0 &&
             !is_root_block_ref(dir_inode_id, &dir_inode, logical_idx, dir_block))) {
            continue;
        }

        read_block(dir_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            dir_entry_t entry = dir->entry[i];
            if (entry.type == EMPTY) {
                continue;
            }
            if (mode == 0 &&
                (!strcmp((char *)entry.name, ".") ||
                 !strcmp((char *)entry.name, ".."))) {
                continue;
            }

            if (mode == 0) {
                prints("%s\n", (char *)entry.name);
            } else {
                inode_t entry_inode;
                fs_read_inode_copy(entry.inode, &entry_inode);
                prints("%s %d %d %s\n",
                       entry.type == DIR ? "dir" : "file",
                       entry_inode.owner, entry_inode.size, (char *)entry.name);
            }
            printed_lines++;
        }
    }

    if (printed_lines == 0) {
        prints("\n");
        printed_lines = 1;
    }

    *print_location_y += printed_lines;
    disable_sum();
    return 1;
}

int do_cd(char* dirname)
{
    uint16_t dir_inode_id;
    uint8_t dir_type;
    inode_t dir_inode;

    enable_sum();
    if (!fs_resolve_path(dirname, 0, &dir_inode_id, &dir_type, NULL, NULL) ||
        dir_type != DIR) {
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(dir_inode_id, &dir_inode);
    current_dir_inode = dir_inode_id;
    current_dir_block = dir_inode.direct_blocks[0];
    disable_sum();
    return 1;
}

int do_link(char* filename, char* newfile, int mode)
{
    uint16_t src_inode_id;
    uint8_t src_type;
    char leaf_name[29];
    uint16_t parent_inode_id;
    uint8_t parent_type;

    enable_sum();
    if (!fs_resolve_path(filename, 0, &src_inode_id, &src_type, NULL, NULL) ||
        src_type != FILE ||
        !fs_resolve_path(newfile, 1, &parent_inode_id, &parent_type, NULL,
                         leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name) ||
        fs_lookup_entry(parent_inode_id, leaf_name, NULL, NULL, NULL)) {
        disable_sum();
        return 0;
    }

    int ret = 0;
    if (mode == 0) {
        inode_t src_inode;
        fs_read_inode_copy(src_inode_id, &src_inode);
        src_inode.link++;
        fs_write_inode_copy(src_inode_id, &src_inode);
        ret = fs_add_entry(parent_inode_id, leaf_name, FILE, src_inode_id);
        if (!ret) {
            src_inode.link--;
            fs_write_inode_copy(src_inode_id, &src_inode);
        }
    } else {
        uint16_t new_inode_id = alloc_inode();
        if (new_inode_id != 0xffff) {
            inode_t src_inode;
            fs_read_inode_copy(src_inode_id, &src_inode);
            src_inode.owner = current_running[cpu_id]->pid;
            src_inode.link = 1;
            fs_write_inode_copy(new_inode_id, &src_inode);
            ret = fs_add_entry(parent_inode_id, leaf_name, FILE, new_inode_id);
            if (!ret) {
                free_inode(new_inode_id);
            }
        }
    }

    disable_sum();
    return ret;
}

